<script setup>
import { ref, computed, onMounted } from 'vue';
import { assetUrl } from '../assets.js';
const props=defineProps({places:Array,selectedId:String});const emit=defineEmits(['select']);const paths=ref([]),zoom=ref(1),pan=ref({x:0,y:0});let gesture;
const merc=lat=>Math.log(Math.tan(Math.PI/4+Math.max(-85,Math.min(85,lat))*Math.PI/360));
function project(lon,lat){return [(lon-70)/72*1000,(merc(55)-merc(lat))/(merc(55)-merc(13))*620]}
const markers=computed(()=>props.places.map(p=>({...p,point:project(p.longitude,p.latitude)})));
const transform=computed(()=>`translate(${pan.value.x} ${pan.value.y}) translate(500 310) scale(${zoom.value}) translate(-500 -310)`);
function start(e){if(e.target.closest('[data-pin]'))return;e.currentTarget.setPointerCapture(e.pointerId);gesture={x:e.clientX,y:e.clientY,px:pan.value.x,py:pan.value.y,w:e.currentTarget.getBoundingClientRect().width}}
function move(e){if(!gesture)return;pan.value={x:gesture.px+(e.clientX-gesture.x)*1000/gesture.w,y:gesture.py+(e.clientY-gesture.y)*1000/gesture.w}}
function reset(){zoom.value=1;pan.value={x:0,y:0}}
onMounted(async()=>{try{const land=await fetch(assetUrl('/textures/land.geojson')).then(r=>r.json());const out=[];for(const f of land.features){const polys=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];for(const poly of polys){if(!poly[0].some(p=>p[0]>65&&p[0]<150&&p[1]>5&&p[1]<65))continue;out.push(poly.map(ring=>ring.map((p,i)=>{const [x,y]=project(...p);return (i?'L':'M')+x.toFixed(2)+' '+y.toFixed(2)}).join(' ')+' Z').join(' '))}}paths.value=out}catch{}});
</script>
<template><div class="offline-geography"><svg viewBox="0 0 1000 620" aria-label="基于真实经纬度的天文地标地图" @pointerdown="start" @pointermove="move" @pointerup="gesture=null" @pointercancel="gesture=null"><defs><pattern id="geo-grid" width="100" height="80" patternUnits="userSpaceOnUse"><path d="M100 0H0V80" fill="none" stroke="#d4e3e8" stroke-width="1"/></pattern></defs><rect width="1000" height="620" fill="#deedf2"/><g :transform="transform"><rect x="-2000" y="-2000" width="5000" height="5000" fill="url(#geo-grid)"/><path v-for="d in paths" :d="d" fill="#ecf0e4" stroke="#bbcdb8" stroke-width="1.2"/><text x="310" y="230" fill="#90a092" font-size="23" letter-spacing="8">东亚地理概览</text><text x="800" y="420" fill="#85a5b6" font-size="20" letter-spacing="5">太平洋</text><g v-for="p in markers" :transform="`translate(${p.point[0]} ${p.point[1]})`" data-pin="true" role="button" tabindex="0" :aria-label="`阅读${p.name}历史与科普介绍`" @click="emit('select',p.id)" @keydown.enter.prevent="emit('select',p.id)" @keydown.space.prevent="emit('select',p.id)"><circle r="13" :fill="selectedId===p.id?'#ba8a4c':'#36677f'" stroke="white" stroke-width="3"/><circle r="4" fill="white"/><g :transform="p.id==='beijing'?'translate(-130 32)':p.id==='xinglong'?'translate(15 -40)':'translate(17 -15)'"><rect x="-7" y="-20" width="142" height="36" rx="6" fill="#fffffff0" stroke="#bccfdb"/><text font-size="15" fill="#2b5369">{{p.name}}</text></g></g></g></svg><div class="offline-map-controls"><button aria-label="放大地理概览" @click="zoom=Math.min(zoom+0.35,4)">＋</button><button aria-label="缩小地理概览" @click="zoom=Math.max(zoom-0.35,0.7)">－</button><button @click="reset">全部地标</button></div><span class="offline-map-caption">本地地理概览 · 可拖动、缩放、点击地标 · Natural Earth 公有领域数据</span></div></template>
<style scoped>.offline-geography{position:absolute;inset:0;background:#deedf2;overflow:hidden}.offline-geography svg{width:100%;height:100%;touch-action:none;cursor:grab}.offline-geography [data-pin]{cursor:pointer}.offline-geography [data-pin]:focus{outline:none}.offline-geography [data-pin]:focus circle:first-child{stroke:#87bfea;stroke-width:7}.offline-map-controls{position:absolute;right:15px;top:80px;display:flex;flex-direction:column;gap:10px}.offline-map-controls button{font-size:12px}.offline-map-caption{position:absolute;bottom:15px;left:18px;right:18px;padding:10px;background:#ffffffd9;color:#678193;font-size:10px;border-radius:7px;pointer-events:none}</style>
